window.futvizVista("perfil-ofensivo","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"perfil-ofensivo\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"perfil-ofensivo\"]={\"id\":\"perfil-ofensivo\",\"titulo\":\"Perfil ofensivo: xG90 vs. xA90\",\"bajada\":\"A la derecha, m\u00e1s xG por 90' (remata); arriba, m\u00e1s xA por 90' (crea). Abre con medios y delanteros.\",\"pregunta\":\"\u00bfQui\u00e9n remata y qui\u00e9n crea?\",\"tabla\":\"jugadores\",\"entidad\":\"jugadores\",\"x\":{\"col\":\"xG90\",\"label\":\"xG por 90'\",\"corto\":\"xG90\",\"dec\":2},\"y\":{\"col\":\"xA90\",\"label\":\"xA por 90'\",\"corto\":\"xA90\",\"dec\":2},\"referencia\":{\"tipo\":\"promedios\",\"cuadrantes\":{\"tl\":\"Crean mucho pero rematan poco\",\"tr\":\"Crean y rematan mucho\",\"br\":\"Rematan mucho pero crean poco\",\"bl\":\"Crean y rematan poco\"},\"cuantil\":0.8},\"requiere\":[\"xG90\",\"xA90\"],\"subtitulo\":\"Jugadores con \u2265{min} min \u00b7 {temporada}\",\"filtros\":{\"posicion\":true,\"nivel\":true,\"sub21\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"xG90\",\"ayuda\":\"Ordenados por xG por 90'\"},{\"id\":\"y\",\"etiqueta\":\"xA90\",\"ayuda\":\"Ordenados por xA por 90'\"}],\"queMirar\":\"Abajo a la derecha, los que rematan entre los mejores sin destacar creando; arriba a la izquierda, al rev\u00e9s; arriba a la derecha, los que hacen las dos cosas. Las l\u00edneas marcan el 20% m\u00e1s alto de cada eje, entre los jugadores que ves. Haz clic en un cuadrante para acercarte a esos jugadores.\\n\\nOjo: **buena parte de la distancia entre dos puntos es el puesto**, no lo bueno que es cada uno. Un central y un extremo caen lej\u00edsimos sin que eso diga nada de ninguno. El filtro de posici\u00f3n deja la comparaci\u00f3n entre iguales.\",\"porQue\":\"Va en tasas por 90 minutos para que un suplente que rinde mucho en poco tiempo no quede sepultado. El corte de minutos (500 en una temporada cerrada; menos en la que va en curso) evita lo contrario: unos pocos minutos con una ocasi\u00f3n clara dan una tasa que es puro ruido.\\n\\nSe usa **xG90 y xA90 en vez de goles y asistencias** porque los goles son un evento raro: lo esperado es una medida m\u00e1s estable de lo que un jugador genera. Los dos ejes correlacionan 0.44: van de la mano solo en parte. Dentro de una posici\u00f3n, y sobre todo entre delanteros, rematar y crear van poco de la mano: son perfiles distintos.\",\"insight\":\"perfil\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\"],\"posicionesIni\":[\"Medio\",\"Delantero\"]};</script>");